import {
  type ColorToken,
  colorTokenVars,
  type ScalarToken,
  scalarTokenVars,
} from '@adhamaa/ui-kit'
import type { Meta, StoryObj } from '@storybook/react-vite'
import type * as React from 'react'

/**
 * Swatches for the Tokens docs page. They read the live CSS variables, so
 * they follow the Theme and Scheme toolbar switches.
 */
const meta = {
  title: 'Tokens',
  // Only shown inside Tokens.mdx.
  tags: ['!autodocs', '!dev'],
  parameters: { layout: 'padded' },
} satisfies Meta

export default meta
type Story = StoryObj<typeof meta>

const colorGroups: { title: string; tokens: ColorToken[] }[] = [
  {
    title: 'Base',
    tokens: ['background', 'foreground', 'muted', 'mutedForeground'],
  },
  {
    title: 'Lines and focus',
    tokens: ['border', 'input', 'ring', 'ringBorder', 'overlay'],
  },
  {
    title: 'Brand',
    tokens: [
      'primary',
      'primaryForeground',
      'primarySoft',
      'primarySoftForeground',
    ],
  },
  {
    title: 'Status',
    tokens: [
      'destructive',
      'destructiveForeground',
      'success',
      'successForeground',
      'warning',
      'warningForeground',
      'info',
      'infoForeground',
    ],
  },
  { title: 'Surfaces', tokens: ['surface', 'surfaceRaised'] },
  {
    title: 'Table',
    tokens: ['tableHeader', 'tableHeaderForeground', 'tableRowHover'],
  },
]

const label: React.CSSProperties = { fontSize: 13, fontWeight: 600 }
const code: React.CSSProperties = {
  fontFamily: 'var(--ui-font-mono)',
  fontSize: 12,
  color: 'var(--ui-muted-foreground)',
}

export const Colors: Story = {
  render: () => (
    <div style={{ display: 'grid', gap: 24 }}>
      {colorGroups.map((group) => (
        <section key={group.title}>
          <h3 style={{ margin: '0 0 8px', fontSize: 14 }}>{group.title}</h3>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fill, minmax(180px, 1fr))',
              gap: 12,
            }}
          >
            {group.tokens.map((token) => (
              <div key={token} style={{ display: 'grid', gap: 6 }}>
                <div
                  style={{
                    height: 56,
                    borderRadius: 'var(--ui-radius)',
                    background: `var(${colorTokenVars[token]})`,
                    border: '1px solid var(--ui-border)',
                  }}
                />
                <span style={label}>{token}</span>
                <span style={code}>{colorTokenVars[token]}</span>
              </div>
            ))}
          </div>
        </section>
      ))}
    </div>
  ),
}

const radii: ScalarToken[] = ['radiusSm', 'radius', 'radiusLg']

export const Radius: Story = {
  render: () => (
    <div style={{ display: 'flex', gap: 24, flexWrap: 'wrap' }}>
      {radii.map((token) => (
        <div key={token} style={{ display: 'grid', gap: 6 }}>
          <div
            style={{
              width: 96,
              height: 64,
              background: 'var(--kit-primary-soft)',
              border: '1px solid var(--ui-primary)',
              borderRadius: `var(${scalarTokenVars[token]})`,
            }}
          />
          <span style={label}>{token}</span>
          <span style={code}>{scalarTokenVars[token]}</span>
        </div>
      ))}
    </div>
  ),
}

const shadows: ScalarToken[] = ['shadow', 'shadowLg']

export const Shadows: Story = {
  render: () => (
    <div style={{ display: 'flex', gap: 32, flexWrap: 'wrap' }}>
      {shadows.map((token) => (
        <div key={token} style={{ display: 'grid', gap: 6 }}>
          <div
            style={{
              width: 140,
              height: 80,
              background: 'var(--kit-surface-raised)',
              borderRadius: 'var(--ui-radius)',
              boxShadow: `var(${scalarTokenVars[token]})`,
            }}
          />
          <span style={label}>{token}</span>
          <span style={code}>{scalarTokenVars[token]}</span>
        </div>
      ))}
    </div>
  ),
}

export const Typography: Story = {
  render: () => (
    <div style={{ display: 'grid', gap: 16 }}>
      <div>
        <div style={{ fontFamily: 'var(--ui-font-sans)', fontSize: 20 }}>
          The quick brown fox jumps over the lazy dog 0123456789
        </div>
        <span style={label}>fontSans</span>{' '}
        <span style={code}>--ui-font-sans</span>
      </div>
      <div>
        <div style={{ fontFamily: 'var(--ui-font-mono)', fontSize: 16 }}>
          PKG-004 · 12,480.50 · {'{ status: "draft" }'}
        </div>
        <span style={label}>fontMono</span>{' '}
        <span style={code}>--ui-font-mono</span>
      </div>
    </div>
  ),
}

const heights = ['xs', 'sm', 'md', 'lg'] as const

export const ControlHeights: Story = {
  render: () => (
    <div style={{ display: 'flex', gap: 16, alignItems: 'flex-end' }}>
      {heights.map((size) => (
        <div
          key={size}
          style={{ display: 'grid', gap: 6, justifyItems: 'center' }}
        >
          <div
            style={{
              width: 64,
              height: `var(--kit-h-${size})`,
              background: 'var(--kit-primary-soft)',
              border: '1px solid var(--ui-primary)',
              borderRadius: 'var(--kit-radius-sm)',
            }}
          />
          <span style={label}>{size}</span>
          <span style={code}>--kit-h-{size}</span>
        </div>
      ))}
    </div>
  ),
}

